```vue
<script setup>
import { ref, watch, onBeforeUnmount } from 'vue';

// what the user typed
const query = ref('');
// what the server found
const results = ref([]);
// show a loader while waiting
const loading = ref(false);
// the debounce timer
let timer;
// the controller of the current request, to cancel it
let controller;

async function search(q) {
  // cancel the previous request: its answer is no longer needed
  controller?.abort();
  // a new controller for this request
  controller = new AbortController();
  // remember this request's signal
  const { signal } = controller;
  loading.value = true;
  try {
    // encodeURIComponent: spaces and & in the query won't break the URL
    const res = await fetch(`/api/search?q=${encodeURIComponent(q)}`, { signal });
    // fetch doesn't throw on 500, check it ourselves
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    results.value = await res.json();
  } catch (error) {
    // AbortError is our own cancel, not a real error
    if (error.name !== 'AbortError') console.error(error);
  } finally {
    // only the latest request turns the loader off
    if (!signal.aborted) loading.value = false;
  }
}

watch(query, (value) => {
  // debounce: every keystroke restarts the timer
  clearTimeout(timer);
  const q = value.trim();
  // empty input: cancel the request and clear the list
  if (!q) {
    controller?.abort();
    results.value = [];
    loading.value = false;
    return;
  }
  // search 300 ms after the last keystroke
  timer = setTimeout(() => search(q), 300);
});

// leaving the page: stop the timer and the request
onBeforeUnmount(() => {
  clearTimeout(timer);
  controller?.abort();
});
</script>

<template>
  <!-- v-model keeps query in sync with the input -->
  <input v-model="query" type="search" placeholder="Search" />
  <!-- the loader while the request is pending -->
  <p v-if="loading">Loading…</p>
  <ul>
    <!-- :key so Vue tracks rows by id, not by position -->
    <li v-for="item in results" :key="item.id">{{ item.title }}</li>
  </ul>
</template>
```

**Where it breaks and what to add in production:**
- No error and "nothing found" states: add `error` and show a message instead of an empty list.
- A minimum query length (2–3 characters), otherwise one letter returns half the database.
- A cache of recent queries: backspace to the previous query shouldn't go to the server again (or use TanStack Query for Vue, which does the cache, cancellation and deduplication).
- Sync the query with the URL (`?q=`), so the search survives a reload and can be shared.
- Accessibility: announce the number of results through `aria-live="polite"`, keyboard navigation through the list (combobox pattern).
- Move the logic into a `useSearch` composable to reuse it and test it separately.

```js
// useFetch.js
import { ref, watchEffect, onScopeDispose, toValue } from 'vue';

export function useFetch(url) {
  // the response data
  const data = ref(null);
  // the error, if the request failed
  const error = ref(null);
  // true while waiting for the response
  const loading = ref(false);
  // the controller of the current request
  let controller;

  watchEffect(async () => {
    // read the URL BEFORE the first await, so watchEffect tracks it
    const currentUrl = toValue(url);
    // cancel the previous request
    controller?.abort();
    controller = new AbortController();
    const { signal } = controller;
    loading.value = true;
    error.value = null;
    try {
      const res = await fetch(currentUrl, { signal });
      // fetch doesn't throw on 4xx/5xx
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      data.value = await res.json();
    } catch (err) {
      // our own cancel isn't an error
      if (err.name !== 'AbortError') error.value = err;
    } finally {
      // only the latest request turns the loader off
      if (!signal.aborted) loading.value = false;
    }
  });

  // the component is destroyed: cancel the request
  onScopeDispose(() => controller?.abort());

  // return refs, the component uses them in the template
  return { data, error, loading };
}
```

